(2653767, 368353, 49326, '<td valign="top">Vá magnað! Mér finnst þessi æði. Ef það væri eitthvað sem ég vildi breyta væri það að gera meiri kontrast í húsin og hlaupabrautina. Annars skiptir það voða litlu máli.</td>', 'Vá magnað! Mér finnst þessi æði. Ef það væri eitthvað sem ég vildi breyta væri það að gera meiri kontrast í húsin og hlaupabrautina. Annars skiptir það voða litlu máli.', '2006-07-24 04:36:39.000000', NULL, 1),
(2653771, 366997, 34938, '<td valign="top">I absolutely adore this shot! How wonderful...I am only thinking I would love to have seel both sets of eyes, but I don;t want to be negative and I certainly won''t take marks away for that...I would love to see this redone minus the grass (?) and perhaps a black background...9</td>', 'I absolutely adore this shot! How wonderful...I am only thinking I would love to have seel both sets of eyes, but I don;t want to be negative and I certainly won''t take marks away for that...I would love to see this redone minus the grass (?) and perhaps a black background...9', '2006-07-24 04:37:48.000000', NULL, 1),
(2653773, 368542, 15032, '<td valign="top">I like the idea, but the highlights are a bit blown out.  A polarizing filter would help to control the reflections.</td>', 'I like the idea, but the highlights are a bit blown out.  A polarizing filter would help to control the reflections.', '2006-07-24 04:38:18.000000', NULL, 1),
