INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2655485, 367438, 16004, '<td valign="top">a superb picture, albeit a bit scary.  the high definition of the eyes are what make it for me, as are other very fantastic details including the precise depth of field, wonderfully complimentary shades of gold, the texture of the hair...  great, unnerving, disturbing, mix of being inspiring and bloody annoying because i know i could never be so creative.  10.</td>', 'a superb picture, albeit a bit scary.  the high definition of the eyes are what make it for me, as are other very fantastic details including the precise depth of field, wonderfully complimentary shades of gold, the texture of the hair...  great, unnerving, disturbing, mix of being inspiring and bloody annoying because i know i could never be so creative.  10.', '2006-07-24 15:40:36.000000', NULL, 1),
(2655487, 368418, 57378, '<td valign="top">Nice fresh feel to it - My only gripe is the blade of grass running infront of the first egg is a little distracting - If there was none I would also feel that would be wrong - Maybe several blades rather than one would have worked.</td>', 'Nice fresh feel to it - My only gripe is the blade of grass running infront of the first egg is a little distracting - If there was none I would also feel that would be wrong - Maybe several blades rather than one would have worked.', '2006-07-24 15:40:48.000000', NULL, 1),
(2655488, 366794, 57519, '<td valign="top">Doesn''t quite make it for the challenge, in my opinion. It is a great macro though.</td>', 'Doesn''t quite make it for the challenge, in my opinion. It is a great macro though.', '2006-07-24 15:41:01.000000', NULL, 1),
