(2657399, 368405, 9232, '<td valign="top">I almost scrolled down too far and rated this; had to scroll back up.  Lovely composition.  Nice use of DoF.  The white object in the lower righthand corner bugs me a little but I like the image overall.  Sense of serenity with the insect''s wings so still.</td>', 'I almost scrolled down too far and rated this; had to scroll back up.  Lovely composition.  Nice use of DoF.  The white object in the lower righthand corner bugs me a little but I like the image overall.  Sense of serenity with the insect''s wings so still.', '2006-07-25 03:49:16.000000', NULL, 1),
(2657406, 365879, 9232, '<td valign="top">You added some interest to this for me with the angle from which you approached your subject.  I''m not thrilled about the crop; since you have already bled the image off the top &amp; left I wouldn''t mind seeing the image less centered and the image cropped as more of a square.  With the cropping you have I get the feeling of a shot where the photographer clipped the top of the head of the subject.  I''m guessing that such was not your intent.  Good idea on the coin.  Better than average score for me.</td>', 'You added some interest to this for me with the angle from which you approached your subject.  I''m not thrilled about the crop; since you have already bled the image off the top & left I wouldn''t mind seeing the image less centered and the image cropped as more of a square.  With the cropping you have I get the feeling of a shot where the photographer clipped the top of the head of the subject.  I''m guessing that such was not your intent.  Good idea on the coin.  Better than average score for me.', '2006-07-25 03:53:03.000000', NULL, 1),
(2657408, 368612, 9232, '<td valign="top">Nice use of thirds.  This image outperforms other landscapes/sunsets in this challenge for me in that gold is the dominant color, none of the colors appear to have much banding, you''ve captured some lovely contrasting textures between the foreground &amp; background and I love the tonal shift as my eyes move up the photo.</td>', 'Nice use of thirds.  This image outperforms other landscapes/sunsets in this challenge for me in that gold is the dominant color, none of the colors appear to have much banding, you''ve captured some lovely contrasting textures between the foreground & background and I love the tonal shift as my eyes move up the photo.', '2006-07-25 03:55:02.000000', NULL, 1),
(2657410, 368235, 9232, '<td valign="top">Good idea but I''m not sold on the execution.  The rose could have been a more robust goldtone instead of being so washed out for my taste.  The gold point of light is surely your intended focal point but my eyes immediately traveled left to the rose as I started to assimilate the story behind the image and the hook you had used with the light just slipped away without the strong flower color to set it.  Good try, tho.</td>', 'Good idea but I''m not sold on the execution.  The rose could have been a more robust goldtone instead of being so washed out for my taste.  The gold point of light is surely your intended focal point but my eyes immediately traveled left to the rose as I started to assimilate the story behind the image and the hook you had used with the light just slipped away without the strong flower color to set it.  Good try, tho.', '2006-07-25 03:57:42.000000', NULL, 1),
(2657414, 366958, 9232, '<td valign="top">Wow, this image really has some potential for me but its just not large enough for me to really tell anything about the edges.  It looks good at this size but I''d like to see a larger version of it.  It looks like good execution.</td>', 'Wow, this image really has some potential for me but its just not large enough for me to really tell anything about the edges.  It looks good at this size but I''d like to see a larger version of it.  It looks like good execution.', '2006-07-25 03:59:34.000000', NULL, 1),
(2657418, 367436, 58801, '<td valign="top">wow, this is really stunning.</td>', 'wow, this is really stunning.', '2006-07-25 04:00:10.000000', NULL, 1),
(2657424, 367005, 9232, '<td valign="top">nice to see someone approach this from a simple point of view.  Clean image, my eyes were drawn to the subject.  Perhaps just a touch too much water for my taste but that doesn''t affect anything.  Nice lighting to keep the interest on the subject.  This is one of the stronger images for me.</td>', 'nice to see someone approach this from a simple point of view.  Clean image, my eyes were drawn to the subject.  Perhaps just a touch too much water for my taste but that doesn''t affect anything.  Nice lighting to keep the interest on the subject.  This is one of the stronger images for me.', '2006-07-25 04:03:00.000000', NULL, 1),
(2657428, 368689, 9232, '<td valign="top">This image of a plain sculpture stands out to me because of the angle from which you chose to see it.  You created some interest through your composition.</td>', 'This image of a plain sculpture stands out to me because of the angle from which you chose to see it.  You created some interest through your composition.', '2006-07-25 04:04:12.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2657430, 368701, 9232, '<td valign="top">Colors are a tad too much for my taste but I appreciate the work on this and the vision that led to this.</td>', 'Colors are a tad too much for my taste but I appreciate the work on this and the vision that led to this.', '2006-07-25 04:04:56.000000', NULL, 1),
(2657433, 367101, 9232, '<td valign="top">For me the ducks/geese and the cloud formation directly over the sun compete with the gold coloring.  They don''t necessarily overpower it but they do detract from its importance in the image for me.</td>', 'For me the ducks/geese and the cloud formation directly over the sun compete with the gold coloring.  They don''t necessarily overpower it but they do detract from its importance in the image for me.', '2006-07-25 04:06:01.000000', NULL, 1),
(2657439, 368594, 9232, '<td valign="top">Creative, not too heavy-handed in its use of "gold".  Good use of composition with leading lines and contrasting lines under the subject that don''t overpower the subject (the gray/silver ink blends into the background too much to compete).  One of my highest images.  I love the subtleties I perceive in this shot.</td>', 'Creative, not too heavy-handed in its use of "gold".  Good use of composition with leading lines and contrasting lines under the subject that don''t overpower the subject (the gray/silver ink blends into the background too much to compete).  One of my highest images.  I love the subtleties I perceive in this shot.', '2006-07-25 04:08:48.000000', NULL, 1),
(2657445, 368690, 9232, '<td valign="top">Wow.  Yet another photo that proves that not all sunsets are created equal . . . well, OK, perhaps this is just evidence that not everyone sees the same thing in a sunset.  You''ve imparted action and interest to this image by turning the camera some and also hiding the element that most people expect to see in a sunset, namely, the sun.  This photo implies the sun and takes advantage of the golden hues to create a lovely tone across the whole image so that I believe the viewer is invited to remember not a specific locale but memories of his/her sunsets at the end of the day out around the water.  Love the camera tilt on this image, too.  Looks like a little bit of banding around some parts of the sunset.</td>', 'Wow.  Yet another photo that proves that not all sunsets are created equal . . . well, OK, perhaps this is just evidence that not everyone sees the same thing in a sunset.  You''ve imparted action and interest to this image by turning the camera some and also hiding the element that most people expect to see in a sunset, namely, the sun.  This photo implies the sun and takes advantage of the golden hues to create a lovely tone across the whole image so that I believe the viewer is invited to remember not a specific locale but memories of his/her sunsets at the end of the day out around the water.  Love the camera tilt on this image, too.  Looks like a little bit of banding around some parts of the sunset.', '2006-07-25 04:12:24.000000', NULL, 1),
(2657449, 368265, 57519, '<td valign="top">Don`t understand the title, but I love cloud pics!</td>', 'Don`t understand the title, but I love cloud pics!', '2006-07-25 04:14:57.000000', NULL, 1),
(2657454, 366824, 57519, '<td valign="top">Needs better focus. The picture could also be larger.</td>', 'Needs better focus. The picture could also be larger.', '2006-07-25 04:20:04.000000', NULL, 1),
