(2659273, 367203, 62739, '<td valign="top">Terrific expression. The hair makes the shot to me. Gives it a goddess feel. As a woman its hard for me to say this but I would have lost the underwear. :D  It takes away a bit from the image, but I still gave it a 10.</td>', 'Terrific expression. The hair makes the shot to me. Gives it a goddess feel. As a woman its hard for me to say this but I would have lost the underwear. :D  It takes away a bit from the image, but I still gave it a 10.', '2006-07-25 17:01:12.000000', NULL, 1),
(2659274, 368602, 62739, '<td valign="top">Very beautiful beach and the birds really make the shot come alive. Nice work.</td>', 'Very beautiful beach and the birds really make the shot come alive. Nice work.', '2006-07-25 17:01:32.000000', NULL, 1),
(2659278, 367448, 62739, '<td valign="top">Very good detail, and nice you have a background worthy of the image. Nice work.</td>', 'Very good detail, and nice you have a background worthy of the image. Nice work.', '2006-07-25 17:01:55.000000', NULL, 1),
(2659279, 368698, 62739, '<td valign="top">The title, the green eyes, the gold paint, it all works to a 10 for me.</td>', 'The title, the green eyes, the gold paint, it all works to a 10 for me.', '2006-07-25 17:02:14.000000', NULL, 1),
(2659283, 366840, 62739, '<td valign="top">Very good lighting on this one. Would have liked those eyes open though. Still a worthy image of a 10.</td>', 'Very good lighting on this one. Would have liked those eyes open though. Still a worthy image of a 10.', '2006-07-25 17:02:54.000000', NULL, 1),
(2659287, 368257, 62739, '<td valign="top">The Golden Apple. Nicely captured. Well enough for a 10 in my book. :D</td>', 'The Golden Apple. Nicely captured. Well enough for a 10 in my book. :D', '2006-07-25 17:03:16.000000', NULL, 1),
(2659288, 367489, 62739, '<td valign="top">Out of all the thumbnails only a very few caught my eye. This was one of them. Love the processing here. Simple, yet very emotive. Very nice work! A big old 10 from me!</td>', 'Out of all the thumbnails only a very few caught my eye. This was one of them. Love the processing here. Simple, yet very emotive. Very nice work! A big old 10 from me!', '2006-07-25 17:03:58.000000', NULL, 1),
