(2660345, 368385, 54540, '<td valign="top">I really like this composition, and the title sells it.  Well done!</td>', 'I really like this composition, and the title sells it.  Well done!', '2006-07-26 01:21:37.000000', NULL, 1),
(2660410, 368432, 54540, '<td valign="top">The amphibian''s eyes match the costume - that sold it for me!  Well done!  (Give the beast a kiss for me!)</td>', 'The amphibian''s eyes match the costume - that sold it for me!  Well done!  (Give the beast a kiss for me!)', '2006-07-26 01:29:39.000000', NULL, 1),
(2660596, 367438, 41008, '<td valign="top">winner. I hope.</td>', 'winner. I hope.', '2006-07-26 01:52:57.000000', NULL, 1),
(2660724, 368655, 54540, '<td valign="top">This is very cool!  I''d give a bonus point if it were less grainy, given the subject matter.  (For me, this colorful subject needs to be REALLY sharp.)  Great choice on the background, really good composition.  Bottom line - 7, maybe nudge to 8 later.  Well done!</td>', 'This is very cool!  I''d give a bonus point if it were less grainy, given the subject matter.  (For me, this colorful subject needs to be REALLY sharp.)  Great choice on the background, really good composition.  Bottom line - 7, maybe nudge to 8 later.  Well done!', '2006-07-26 02:10:23.000000', NULL, 1),
(2660730, 368203, 54540, '<td valign="top">That reeks of GOLD!  Nice.</td>', 'That reeks of GOLD!  Nice.', '2006-07-26 02:10:58.000000', NULL, 1),
(2660756, 367620, 28359, '<td valign="top">Great shot! the lighting is perfect, the pose fits with the sceen nicely....10</td>', 'Great shot! the lighting is perfect, the pose fits with the sceen nicely....10', '2006-07-26 02:14:02.000000', NULL, 1),
(2660848, 367438, 62812, '<td valign="top">horrific - i love it</td>', 'horrific - i love it', '2006-07-26 02:36:40.000000', NULL, 1),
(2660968, 365911, 54540, '<td valign="top">Very cool capture!</td>', 'Very cool capture!', '2006-07-26 03:02:16.000000', NULL, 1),
(2661135, 366535, 54540, '<td valign="top">Very cool idea!  I would like to see the great circle in focus too, that would kick it up another notch.  (in other words, trying a higher f-stop to get more in focus.)</td>', 'Very cool idea!  I would like to see the great circle in focus too, that would kick it up another notch.  (in other words, trying a higher f-stop to get more in focus.)', '2006-07-26 03:19:00.000000', NULL, 1),
