INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2661395, 368643, 54540, '<td valign="top">Cool idea.  I would go with a larger image however (640 pixels max) and more focus/sharpness, to emphasize the gold on the tuning post.  Excellent composition!  (Your caught my eye to write this comment!)</td>', 'Cool idea.  I would go with a larger image however (640 pixels max) and more focus/sharpness, to emphasize the gold on the tuning post.  Excellent composition!  (Your caught my eye to write this comment!)', '2006-07-26 03:50:10.000000', NULL, 1),
(2661400, 367989, 54540, '<td valign="top">I like the background bokeh.</td>', 'I like the background bokeh.', '2006-07-26 03:53:11.000000', NULL, 1),
(2661919, 368710, 14671, '<td valign="top">At first glance the image size make the overall photo hard to look at because a lot of the detail is lost in its size.  The gold flake mixed in with the dark background is a nice touch and it does fits the challenge.  The subject also lacks interest as well dues to its size.  Goodluck in this challenge. &lt;5&gt;</td>', 'At first glance the image size make the overall photo hard to look at because a lot of the detail is lost in its size.  The gold flake mixed in with the dark background is a nice touch and it does fits the challenge.  The subject also lacks interest as well dues to its size.  Goodluck in this challenge. <5>', '2006-07-26 05:53:33.000000', NULL, 1),
(2661927, 368417, 14671, '<td valign="top">While the photo certainly fits the challenge the photo is not one I''d expect to see on a wall.  The photo also looks a little over sharpened or pixelated on the building.  Good luck in this challenge.  &lt;5&gt;</td>', 'While the photo certainly fits the challenge the photo is not one I''d expect to see on a wall.  The photo also looks a little over sharpened or pixelated on the building.  Good luck in this challenge.  <5>', '2006-07-26 05:56:33.000000', NULL, 1),
(2661939, 365769, 14671, '<td valign="top">Certainly an interesting photo.  I would like to know who this was done.  The clarity and crispness is very good and there only one little hotspot on the cap of the bottle thats distracting yet adds a certain commercial quality to this photo.  Well done and good luck in this challenge.  &lt;7&gt;</td>', 'Certainly an interesting photo.  I would like to know who this was done.  The clarity and crispness is very good and there only one little hotspot on the cap of the bottle thats distracting yet adds a certain commercial quality to this photo.  Well done and good luck in this challenge.  <7>', '2006-07-26 06:02:32.000000', NULL, 1),
(2661944, 365869, 14671, '<td valign="top">Interesting for an almost abstract look but the clarity isn''t all that great.  While it does meet the challenge the image is just to blurry to vote higher then &lt;5&gt;.  Good luck in this challenge.</td>', 'Interesting for an almost abstract look but the clarity isn''t all that great.  While it does meet the challenge the image is just to blurry to vote higher then <5>.  Good luck in this challenge.', '2006-07-26 06:04:12.000000', NULL, 1),
(2661949, 368244, 14671, '<td valign="top">I think this would make an excellent image for the zen challenge and IMO barely fits for this challenge.  The image is a little to dark for my taste but it does have a certain mysterious feeling about it.  Well done and good luck in this challenge.  &lt;8&gt;</td>', 'I think this would make an excellent image for the zen challenge and IMO barely fits for this challenge.  The image is a little to dark for my taste but it does have a certain mysterious feeling about it.  Well done and good luck in this challenge.  <8>', '2006-07-26 06:07:19.000000', NULL, 1),
(2661966, 368427, 14671, '<td valign="top">Interesting capture. Excellent colors and clarity.  I''ve been looking at this photo for about 5 min. now and actually have nothing to say about it.  I know its level but perhaps leveling the graffiti instead of the sidewalk would have had a greater impact for/on me.  Good luck in this challenge.  &lt;6&gt;</td>', 'Interesting capture. Excellent colors and clarity.  I''ve been looking at this photo for about 5 min. now and actually have nothing to say about it.  I know its level but perhaps leveling the graffiti instead of the sidewalk would have had a greater impact for/on me.  Good luck in this challenge.  <6>', '2006-07-26 06:11:21.000000', NULL, 1),
(2661988, 366260, 14671, '<td valign="top">As level as the photo is the subject isn''t level.  You can see what I''m refering to in the glass where the head/foam meets the beer in comparison to the rim of the glass.  However the image is very clear and has great color and the reflection adds that much more to the photo then it would have without.  There''s also no noticable finger prints on the glass which is refreshing not to see.  Nice Ad style shot and something I will expect to see passing a billboard on the highway one day.  Well done and good luck in this challenge.  &lt;6&gt;</td>', 'As level as the photo is the subject isn''t level.  You can see what I''m refering to in the glass where the head/foam meets the beer in comparison to the rim of the glass.  However the image is very clear and has great color and the reflection adds that much more to the photo then it would have without.  There''s also no noticable finger prints on the glass which is refreshing not to see.  Nice Ad style shot and something I will expect to see passing a billboard on the highway one day.  Well done and good luck in this challenge.  <6>', '2006-07-26 06:17:26.000000', NULL, 1),
(2661991, 366827, 61863, '<td valign="top">Very well taken - good job</td>', 'Very well taken - good job', '2006-07-26 06:17:45.000000', NULL, 1),
(2661992, 368453, 61863, '<td valign="top">Great photo, lovely dog</td>', 'Great photo, lovely dog', '2006-07-26 06:18:29.000000', NULL, 1),
(2661995, 366780, 61863, '<td valign="top">Simple but vey well done</td>', 'Simple but vey well done', '2006-07-26 06:18:54.000000', NULL, 1),
(2662008, 366720, 14671, '<td valign="top">While you should be shot for abusing such a classic movie I''ll forgive you this time in the name of photography.  While the photo certainly meets the challenge this type of shot is one I''d expect to see walking into a movie rental store advertising popcorn or movies etc.  Excellent color and clarity and no harsh hotspots.  Well done and and may the force be with you.  &lt;7&gt;</td>', 'While you should be shot for abusing such a classic movie I''ll forgive you this time in the name of photography.  While the photo certainly meets the challenge this type of shot is one I''d expect to see walking into a movie rental store advertising popcorn or movies etc.  Excellent color and clarity and no harsh hotspots.  Well done and and may the force be with you.  <7>', '2006-07-26 06:23:02.000000', NULL, 1),
(2662019, 367444, 14671, '<td valign="top">I find the sun to be very harsh in this photo but kinda like the way it is when you actually look at this shot in real life.  The grass is a little OoF and because of the brightness of the sun you lose a lot of clarity/details.  Good luck in this challenge.  &lt;5&gt;  up''ed to &lt;6&gt; for following the RoT.</td>', 'I find the sun to be very harsh in this photo but kinda like the way it is when you actually look at this shot in real life.  The grass is a little OoF and because of the brightness of the sun you lose a lot of clarity/details.  Good luck in this challenge.  <5>  up''ed to <6> for following the RoT.', '2006-07-26 06:26:40.000000', NULL, 1),
(2662068, 368620, 14671, '<td valign="top">wow the perspective of the 2 buildings makes the tower look slightly tilted even tho its not.  Excellent clarity, fantastic colors and great comp.  Well done and good luck in this challenge.  &lt;7&gt;</td>', 'wow the perspective of the 2 buildings makes the tower look slightly tilted even tho its not.  Excellent clarity, fantastic colors and great comp.  Well done and good luck in this challenge.  <7>', '2006-07-26 06:40:50.000000', NULL, 1),
