(2675655, 367257, 34938, '<td valign="top">I like the close crop and the sharpness in the middle...bumping up</td>', 'I like the close crop and the sharpness in the middle...bumping up', '2006-07-30 04:44:04.000000', NULL, 1),
(2675657, 368606, 34938, '<td valign="top">good title and an almost abstract image...lighting is good...bumping up</td>', 'good title and an almost abstract image...lighting is good...bumping up', '2006-07-30 04:44:44.000000', NULL, 1),
