(2676444, 368572, 49865, '<td valign="top">I''m  a bit curious to know what this is, but it''s a wonderful subject for the Gold challenge. It does have a very strange, alien, dream-like quality to it.</td>', 'I''m  a bit curious to know what this is, but it''s a wonderful subject for the Gold challenge. It does have a very strange, alien, dream-like quality to it.', '2006-07-30 17:12:49.000000', NULL, 1),
(2676446, 368434, 49865, '<td valign="top">There appears to be some sort of cobweb/dangling thread from the top of the torch that may have been brushed off prior to shooting. This is a good idea for a subject though. It may have been better against a simple or highly out-of-focus background, where there is less to distract the viewer.</td>', 'There appears to be some sort of cobweb/dangling thread from the top of the torch that may have been brushed off prior to shooting. This is a good idea for a subject though. It may have been better against a simple or highly out-of-focus background, where there is less to distract the viewer.', '2006-07-30 17:14:54.000000', NULL, 1),
(2676447, 368633, 49865, '<td valign="top">I like the image a lot but I am not a fan of the border.</td>', 'I like the image a lot but I am not a fan of the border.', '2006-07-30 17:15:24.000000', NULL, 1),
