(2678480, 368227, 21816, '<td valign="top">I thought this was a very well composed shot and the lighting does give her skin a nice golden glow! Well done!</td>', 'I thought this was a very well composed shot and the lighting does give her skin a nice golden glow! Well done!', '2006-07-31 04:34:27.000000', NULL, 0),
(2678484, 367436, 21816, '<td valign="top">I really love the texture the fabric adds to this shot. In contrast to a previous comment I think it is very well done.</td>', 'I really love the texture the fabric adds to this shot. In contrast to a previous comment I think it is very well done.', '2006-07-31 04:35:46.000000', NULL, 0),
(2678488, 367963, 57166, '<td valign="top">I really thought this image would do better then it did.  It was a 9 for me even with fuzzy birds.  Tough crowd here.  Well done!!</td>', 'I really thought this image would do better then it did.  It was a 9 for me even with fuzzy birds.  Tough crowd here.  Well done!!', '2006-07-31 04:36:55.000000', NULL, 0),
(2678494, 368542, 57166, '<td valign="top">I guess most don''t share my love of chocolate or my vote of 10.  I thought this was a great idea, still do.  Well done!!</td>', 'I guess most don''t share my love of chocolate or my vote of 10.  I thought this was a great idea, still do.  Well done!!', '2006-07-31 04:37:51.000000', NULL, 0),
(2678497, 368711, 57166, '<td valign="top">Wow, this didnt do near as well as i projected.  I love it, its really beautiful and calming.  Nice work that deserved a far higher score. btw it was a 9 for me.<br/><br/><i>Message edited by author 2006-07-31 03:39:24.</i></td>', 'Wow, this didnt do near as well as i projected.  I love it, its really beautiful and calming.  Nice work that deserved a far higher score. btw it was a 9 for me.', '2006-07-31 04:39:01.000000', '2006-07-31 04:39:24.000000', 0),
