(2678605, 368690, 30861, '<td valign="top">Very nicely done, arty!</td>', 'Very nicely done, arty!', '2006-07-31 05:53:49.000000', NULL, 0),
(2678608, 368532, 30861, '<td valign="top">This was the only 10 I gave. I can''t believe it finished so far down... Hell of a shot.</td>', 'This was the only 10 I gave. I can''t believe it finished so far down... Hell of a shot.', '2006-07-31 05:56:10.000000', NULL, 0),
